<?php
require_once __DIR__.'/config/config.php'; require_login();
$pageTitle='Clientes'; $active='clientes'; $error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$nombre=trim($_POST['nombre']??'');if($nombre==='')throw new RuntimeException('El nombre es obligatorio.');db()->prepare('INSERT INTO clientes(tipo_documento,documento,nombre,telefono,correo,direccion) VALUES(?,?,?,?,?,?)')->execute([$_POST['tipo_documento']??'NIT',trim($_POST['documento']??'')?:null,$nombre,trim($_POST['telefono']??''),trim($_POST['correo']??''),trim($_POST['direccion']??'')]);$success='Cliente registrado.';}catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'No se pudo guardar. Verifica si el documento ya está registrado.';}}
$rows=[];try{$rows=db()->query('SELECT c.*,COALESCE((SELECT SUM(v.total-v.abonado) FROM ventas v WHERE v.cliente_id=c.id AND v.estado<>"Anulada"),0) cartera FROM clientes c ORDER BY c.nombre')->fetchAll();}catch(Throwable $ex){}
include __DIR__.'/includes/header.php';
?>
<?php if($error): ?><div class="notice danger"><?=e($error)?></div><?php endif;if($success): ?><div class="notice success"><?=e($success)?></div><?php endif; ?>
<section class="form-panel"><h2>Registrar cliente</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Tipo documento<select name="tipo_documento"><option>NIT</option><option>CC</option><option>CE</option><option>Pasaporte</option><option>Otro</option></select></label><label>Documento<input name="documento"></label><label>Nombre / razón social<input name="nombre" required></label><label>Teléfono<input name="telefono"></label><label>Correo electrónico<input type="email" name="correo"></label><label>Dirección<input name="direccion"></label></div><button class="btn primary">Guardar cliente</button></form></section>
<section class="table-panel"><div class="table-toolbar"><b>Directorio de clientes</b><input class="quick-search" placeholder="Buscar cliente..." data-table-search="clients-table"></div><div class="table-scroll"><table id="clients-table"><thead><tr><th>Documento</th><th>Cliente</th><th>Teléfono</th><th>Correo</th><th>Dirección</th><th class="numeric">Cartera pendiente</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['tipo_documento'].' '.($r['documento']??''))?></td><td><b><?=e($r['nombre'])?></b></td><td><?=e($r['telefono'])?></td><td><?=e($r['correo'])?></td><td><?=e($r['direccion'])?></td><td class="numeric"><?=money($r['cartera'])?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="empty">No hay clientes registrados.</td></tr><?php endif; ?></tbody></table></div></section>
<?php include __DIR__.'/includes/footer.php'; ?>
